test('hyperframes-create: mọi lệnh qua ./hf; wrapper mang biến tắt telemetry và tự cài skill, chạy được ở shell mới', () => {
  const hf = fs.readFileSync(path.join(root, '..', 'hyperframes-create', 'SKILL.md'), 'utf8');
  assert.ok(hf.includes('`./hf init <tên-project> --skip-skills`'));
  assert.ok(!/(^|[^-])npx hyperframes/m.test(hf), 'không còn npx hyperframes trần');
  for (const c of ['lint', 'check --json', 'snapshot', 'preview --background', 'render --quality']) assert.ok(hf.includes(`./hf ${c}`), c);
  const line = hf.split('\n').find((l) => l.trim().startsWith("printf '%s\\n' '#!/bin/sh'")).trim();
  const dir = fs.mkdtempSync(path.join(os.tmpdir(), 'hf-wrap-'));
  try {
    fs.mkdirSync(path.join(dir, 'bin'));
    fs.writeFileSync(path.join(dir, 'bin', 'npx'), '#!/bin/sh\necho "T=$HYPERFRAMES_NO_TELEMETRY S=$HYPERFRAMES_SKIP_SKILLS ARGS=$*"\n', { mode: 0o755 });
    execFileSync('sh', ['-c', line], { cwd: dir });
    const env = { ...process.env, PATH: `${path.join(dir, 'bin')}:${process.env.PATH}` };
    delete env.HYPERFRAMES_NO_TELEMETRY; delete env.HYPERFRAMES_SKIP_SKILLS;
    // init in the task folder makes the project subfolder; the wrapper is copied in; later calls are new shells there.
    const init = execFileSync('sh', ['-c', './hf init demo --skip-skills && mkdir demo && cp hf demo/hf'], { cwd: dir, env, encoding: 'utf8' });
    assert.equal(init.trim(), 'T=1 S=1 ARGS=--no-install hyperframes init demo --skip-skills');
    assert.ok(hf.includes('cp hf <tên-project>/hf'));
    assert.ok(hf.includes('cd ~/company/video/<id-phiếu>/<tên-project> && ./hf <lệnh>'));
    for (const args of [['lint'], ['check', '--json']]) {   // (each call is its own shell, started in the project)
      const out = execFileSync('sh', ['-c', `./hf ${args.join(' ')}`], { cwd: path.join(dir, 'demo'), env, encoding: 'utf8' });
      assert.equal(out.trim(), `T=1 S=1 ARGS=--no-install hyperframes ${args.join(' ')}`);
    }
  } finally { fs.rmSync(dir, { recursive: true, force: true }); }
});

